(function () {
const html = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Education Planning</title>\n  <!-- Google Fonts & Lucide Icons -->\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=DM+Mono:ital,wght@0,300;0,400;0,500;0,700;1,400&family=DM+Sans:ital,opsz,wght@0,9..40,100..1000;1,9..40,100..1000&display=swap\" rel=\"stylesheet\">\n  <script src=\"https://unpkg.com/lucide@latest\"></script>\n  <!-- Vue 3 CDN -->\n  <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n  \n  <style>\n    /* \u2500\u2500 DIRECT PORT OF UPLOADED CSS \u2500\u2500 */\n    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n    :root {\n      --bg: #f7f6f2; --surface: #fff; --surface2: #f2f0eb;\n      --border: #e2dfd8; --border-strong: #c8c4bb;\n      --text: #1a1916; --text2: #6b6860; --text3: #a09d98;\n      --green: #1a6b47; --green-bg: #edf7f2;\n      --blue: #1a4a6b; --blue-bg: #edf3f7;\n      --red: #6b1a1a; --red-bg: #f7eded;\n      --gold: #6b4e1a; --gold-bg: #f7f2ed;\n      --orange: #b85c00; --amber: #c97a1a;\n      --r: 6px; --rl: 10px;\n      --shadow: 0 1px 3px rgba(0,0,0,0.06);\n      --shadow-md: 0 4px 12px rgba(0,0,0,0.05);\n      --purple: #5f3dc4; --purple-light: #f1ecff;\n    }\n    body { font-family:'DM Sans',sans-serif; background:var(--bg); color:var(--text); font-size:14px; line-height:1.5; min-height:100vh; }\n\n    /* \u2500\u2500 TOPBAR \u2500\u2500 */\n    .topbar { background:var(--surface); border-bottom:1px solid var(--border); padding:0 1.5rem; display:flex; align-items:center; justify-content:space-between; height:56px; position:sticky; top:0; z-index:200; }\n    .brand { display:flex; align-items:center; gap:10px; }\n    .brand-mark { width:28px; height:28px; background:var(--text); border-radius:6px; display:flex; align-items:center; justify-content:center; flex-shrink:0; }\n    .brand-mark svg { width:14px; height:14px; stroke: #fff; stroke-width: 2.5; fill: none; }\n    .brand-name { font-size:14px; font-weight:500; letter-spacing:-0.01em; }\n    .brand-sub { font-size:12px; color:var(--text3); margin-left:2px; }\n    .pill-nav { display:flex; background:var(--surface2); border-radius:20px; padding:3px; gap:2px; }\n    .pill-btn { padding:5px 16px; border-radius:16px; border:none; background:transparent; font-size:12px; font-family:'DM Sans',sans-serif; color:var(--text2); cursor:pointer; font-weight:400; transition:all .15s; display:flex; align-items:center; gap:6px; }\n    .pill-btn.active { background:var(--surface); color:var(--text); font-weight:500; box-shadow:0 1px 2px rgba(0,0,0,.08); }\n\n    /* \u2500\u2500 PAGE SHELLS \u2500\u2500 */\n    .page { display:none; }\n    .page.active { display:flex; min-height:calc(100vh - 56px); }\n\n    /* \u2500\u2500 ENTRY LAYOUT \u2500\u2500 */\n    .sidebar { width:260px; flex-shrink:0; background:var(--surface); border-right:1px solid var(--border); position:sticky; top:56px; height:calc(100vh - 56px); overflow-y:auto; padding:1.25rem 0; display:flex; flex-direction:column; justify-content:space-between; }\n    .sidebar-top { flex: 1; }\n    .main-area { flex:1; padding:2rem; overflow-y:auto; min-width:0; }\n\n    /* sidebar nav */\n    .sb-label { font-size:10px; font-weight:500; letter-spacing:.08em; text-transform:uppercase; color:var(--text3); padding:0 1.25rem; margin-bottom:.5rem; margin-top:1.5rem; }\n    .sb-label:first-of-type { margin-top:0; }\n    .sb-item { display:flex; align-items:center; gap:10px; padding:9px 1.25rem; cursor:pointer; border-left:2px solid transparent; transition:all .12s; font-size:13px; color:var(--text2); text-decoration:none; }\n    .sb-item:hover { background:var(--surface2); color:var(--text); }\n    .sb-item.active { border-left-color:var(--text); color:var(--text); font-weight:500; background:var(--surface2); }\n    .sb-dot { width:6px; height:6px; border-radius:50%; flex-shrink:0; }\n    .d1 { background:var(--green); } .d2 { background:var(--blue); } .d3 { background:var(--gold); } .d4 { background:var(--text3); }\n\n    /* progress */\n    .prog-wrap { padding:1.25rem 1.25rem .75rem; }\n    .prog-top { display:flex; justify-content:space-between; font-size:11px; color:var(--text3); margin-bottom:6px; }\n    .prog-track { height:4px; background:var(--surface2); border-radius:2px; overflow:hidden; }\n    .prog-fill { height:100%; background:var(--text); border-radius:2px; width:0%; transition:width .4s; }\n\n    /* per-segment sidebar summaries */\n    .seg-sum { display:none; margin:0 1rem .75rem; }\n    .seg-sum.on { display:block; }\n    .ss-head { color:#fff; font-size:10px; font-weight:500; letter-spacing:.06em; text-transform:uppercase; padding:6px 10px; border-radius:var(--r) var(--r) 0 0; }\n    .ss-body { background:var(--surface2); border-radius:0 0 var(--r) var(--r); padding:8px 10px; border:1px solid var(--border); border-top:none; }\n    .ss-row { display:flex; justify-content:space-between; align-items:baseline; padding:4px 0; font-size:11px; color:var(--text2); border-bottom:1px solid var(--border); }\n    .ss-row:last-child { border-bottom:none; }\n    .ss-row.neg { color:var(--red); }\n    .ss-v { font-family:'DM Mono',monospace; font-size:11px; color:var(--text); }\n    .ss-b { font-weight:500; }\n    .ss-div { height:1px; background:var(--border-strong); margin:5px 0; }\n    .ss-tot { display:flex; justify-content:space-between; align-items:baseline; padding:3px 0; font-size:11px; font-weight:500; }\n    .positive { color:var(--green); } .negative { color:var(--red); } .neutral { color:var(--blue); } .warning { color:var(--amber); }\n\n    /* \u2500\u2500 SEGMENT CONTENT \u2500\u2500 */\n    .segment { display:none; }\n    .segment.active { display:block; }\n    .seg-hdr { display:flex; align-items:flex-start; justify-content:space-between; margin-bottom:1.75rem; gap:12px; }\n    .seg-tag { display:inline-flex; align-items:center; padding:3px 10px; border-radius:20px; font-size:11px; font-weight:500; margin-bottom:6px; }\n    .t1{background:var(--green-bg);color:var(--green);} .t2{background:var(--blue-bg);color:var(--blue);} .t3{background:var(--gold-bg);color:var(--gold);} .t4{background:var(--surface2);color:var(--text2);}\n    .seg-title { font-size:22px; font-weight:300; letter-spacing:-.03em; }\n    .seg-desc { font-size:13px; color:var(--text3); margin-top:4px; }\n    .seg-tot-box { text-align:right; background:var(--surface2); border-radius:var(--rl); padding:10px 16px; border: 1px solid var(--border); }\n    .tot-label { font-size:11px; color:var(--text3); }\n    .tot-val { font-size:20px; font-weight:500; font-family:'DM Mono',monospace; letter-spacing:-.03em; }\n\n    /* cards */\n    .card { background:var(--surface); border:1px solid var(--border); border-radius:var(--rl); margin-bottom:1rem; overflow:hidden; box-shadow:var(--shadow); }\n    .ch { display:flex; align-items:center; justify-content:space-between; padding:12px 16px; cursor:pointer; user-select:none; border-bottom:1px solid transparent; transition:background .12s; }\n    .ch:hover { background:var(--surface2); }\n    .ch.open { border-bottom-color:var(--border); }\n    .ch-left { display:flex; align-items:center; gap:10px; }\n    .ci { width:28px; height:28px; border-radius:6px; display:flex; align-items:center; justify-content:center; font-size:13px; flex-shrink:0; }\n    .ci1{background:var(--green-bg); color:var(--green);} \n    .ci2{background:var(--blue-bg); color:var(--blue);} \n    .ci3{background:var(--gold-bg); color:var(--gold);} \n    .ci-r{background:var(--red-bg); color:var(--red);} \n    .ci-g{background:var(--surface2); color:var(--text2);}\n    .ch-title { font-size:13px; font-weight:500; }\n    .ch-sub { font-size:11px; color:var(--text3); margin-top:1px; }\n    .ch-right { display:flex; align-items:center; gap:10px; }\n    .ch-sum { font-family:'DM Mono',monospace; font-size:13px; color:var(--text2); }\n    .chev { width:16px; height:16px; color:var(--text3); transition:transform .2s; flex-shrink:0; display:flex; align-items:center; justify-content:center; }\n    .chev.open { transform:rotate(180deg); }\n    .cb { display:none; padding:14px 16px; background: #fff; }\n    .cb.open { display:block; }\n\n    /* fields */\n    .f-static { display:grid; grid-template-columns:260px 1fr ; gap:12px; align-items:center; padding:10px 0; border-bottom:1px solid var(--border); }\n    .f-static:last-of-type { border-bottom:none; }\n    .f-label { font-size:13px; font-weight:500; }\n    .f-sub { font-size:11px; color:var(--text3); font-weight:400; margin-top:1px; }\n    .pfx-wrap { position:relative; width: 100%; }\n    .pfx { position:absolute; left:12px; top:50%; transform:translateY(-50%); font-size:12px; color:var(--text3); pointer-events:none; }\n    .sfx { position:absolute; right:12px; top:50%; transform:translateY(-50%); font-size:12px; color:var(--text3); pointer-events:none; }\n    .inp { width:100%; height:34px; border:1px solid var(--border); border-radius:var(--r); padding:0 10px; font-size:13px; font-family:'DM Mono',monospace; color:var(--text); background:var(--surface); text-align:right; transition:border-color .12s; }\n    .inp:focus { outline:none; border-color:var(--text); }\n    .inp.pl { padding-left:28px; text-align:left; }\n    .inp.pr { padding-right:28px; text-align:right; }\n    .inp-t { height:34px; border:1px solid var(--border); border-radius:var(--r); padding:0 10px; font-size:13px; font-family:'DM Sans',sans-serif; color:var(--text); background:var(--surface); width:100%; transition:border-color .12s; }\n    .inp-t:focus { outline:none; border-color:var(--text); }\n    \n    .btn-rm { width:28px; height:28px; border:1px solid var(--border); border-radius:var(--r); background:transparent; cursor:pointer; color:var(--text3); display:flex; align-items:center; justify-content:center; transition:all .12s; }\n    .btn-rm:hover { border-color:var(--red); color:var(--red); background:var(--red-bg); }\n    .btn-add { display:flex; align-items:center; justify-content:center; gap:6px; padding:8px 12px; border:1px dashed var(--border-strong); border-radius:var(--r); background:transparent; font-size:12px; font-family:'DM Sans',sans-serif; color:var(--text3); cursor:pointer; margin-top:4px; width:100%; transition:all .12s; }\n    .btn-add:hover { border-color:var(--text); color:var(--text2); background:var(--surface2); }\n\n    /* nav buttons */\n    .seg-nav { display:flex; justify-content:space-between; align-items:center; margin-top:2rem; padding-top:1.5rem; border-top:1px solid var(--border); }\n    .btn-nav { display:flex; align-items:center; gap:6px; padding:9px 18px; border:1px solid var(--border); border-radius:var(--r); background:transparent; font-size:13px; font-family:'DM Sans',sans-serif; color:var(--text2); cursor:pointer; transition:all .12s; }\n    .btn-nav:hover { border-color:var(--text); color:var(--text); }\n    .btn-pri { background:var(--text); color:#fff; border-color:var(--text); }\n    .btn-pri:hover { background:#333; }\n\n    /* \u2500\u2500 ANALYSIS PAGE \u2500\u2500 */\n    #page-analysis .main-area { max-width:1100px; margin:0 auto; }\n    .a-header { margin-bottom:1.75rem; display:flex; align-items:flex-start; justify-content:space-between; gap:1rem; flex-wrap:wrap; }\n    .a-header-left .a-title { font-size:28px; font-weight:300; letter-spacing:-.03em; }\n    .a-header-left .a-sub { font-size:13px; color:var(--text3); margin-top:4px; }\n    .sec-title { font-size:10px; font-weight:500; letter-spacing:.08em; text-transform:uppercase; color:var(--text3); margin-bottom:.75rem; margin-top:1.5rem; }\n\n    /* quadrant */\n    .quad-grid { display:grid; grid-template-columns:repeat(2, minmax(0,1fr)); gap:10px; margin-bottom:1rem; }\n    .quad-card { border-radius:var(--rl); overflow:hidden; border:1px solid var(--border); cursor:pointer; transition:transform .15s, box-shadow .15s; }\n    .quad-card:hover { transform:translateY(-2px); box-shadow:0 6px 20px rgba(0,0,0,.1); }\n    .quad-card:active { transform:translateY(0); box-shadow:none; }\n    .q-hint { font-size:10px; color:rgba(255,255,255,.7); font-style:italic; float:right; font-weight:400; letter-spacing:0; }\n    .q-head { padding:8px 12px; font-size:11px; font-weight:500; letter-spacing:.05em; text-transform:uppercase; color:#fff; }\n    .qg{background:#1a6b47;} .qr{background:#8b2020;} .qb{background:#1a4a6b;} .qo{background:#b85c00;}\n    .q-body { background:var(--surface); padding:10px 12px; }\n    .q-row { display:flex; justify-content:space-between; padding:4px 0; font-size:12px; color:var(--text2); border-bottom:1px solid var(--surface2); }\n    .q-row:last-child { border-bottom:none; }\n    .q-val { font-family:'DM Mono',monospace; font-size:12px; font-weight:500; color:var(--text); }\n    .q-div { height:1px; background:var(--border); margin:6px 0; }\n    .q-foot { display:flex; justify-content:space-between; padding:4px 0 0; font-size:12px; font-weight:500; }\n    .q-fv { font-family:'DM Mono',monospace; font-size:13px; font-weight:500; }\n\n    /* matrix / KPI strip */\n    .kpi-grid { display:grid; grid-template-columns:repeat(4, minmax(0,1fr)); gap:10px; margin-bottom:1.5rem; }\n    .kpi { background:var(--surface); border:1px solid var(--border); border-radius:var(--rl); padding:1rem 1.25rem; }\n    .kpi-lbl { font-size:11px; color:var(--text3); letter-spacing:.03em; margin-bottom:6px; }\n    .kpi-val { font-size:20px; font-weight:500; font-family:'DM Mono',monospace; letter-spacing:-.03em; }\n    .kpi-sub { font-size:11px; color:var(--text3); margin-top:4px; }\n    .kpi-val.surplus { color:#1a6b47; font-weight:700; }\n    .kpi-val.deficit { color:#8b2020; font-weight:700; }\n\n    /* analysis cards */\n    .a-card { background:var(--surface); border:1px solid var(--border); border-radius:var(--rl); padding:1.25rem; margin-bottom:1rem; }\n    .a-card-title { font-size:13px; font-weight:500; margin-bottom:1rem; display:flex; align-items:center; gap:8px; }\n    .a-dot { width:8px; height:8px; border-radius:50%; flex-shrink:0; }\n    .two-col { display:grid; grid-template-columns:1fr 1fr; gap:1rem; margin-bottom:1rem; }\n    \n    .bk-table { width:100%; border-collapse:collapse; }\n    .bk-table th { font-size:11px; font-weight:500; color:var(--text3); text-align:left; padding:0 0 8px; border-bottom:1px solid var(--border); }\n    .bk-table th:last-child { text-align:right; }\n    .bk-table td { padding:8px 0; font-size:13px; border-bottom:1px solid var(--surface2); vertical-align:middle; }\n    .bk-table td:last-child { text-align:right; font-family:'DM Mono',monospace; font-weight:500; }\n    .bk-table tr:last-child td { border-bottom:none; }\n\n    .ratio-item { display:flex; align-items:center; gap:8px; margin-bottom:8px; }\n    .ratio-lbl { font-size:12px; color:var(--text2); width:130px; flex-shrink:0; }\n    .ratio-track { flex:1; background:var(--surface2); height:8px; border-radius:4px; overflow:hidden; }\n    .ratio-fill { height:100%; border-radius:4px; }\n    .ratio-pct { font-size:12px; font-family:'DM Mono',monospace; width:45px; text-align:right; }\n\n    .empty-state { text-align:center; padding:4rem 1rem; color:var(--text3); }\n    .empty-state a { color:var(--blue); text-decoration:none; font-weight:500; cursor:pointer; }\n\n    /* group blocks */\n    .grp-block { background:var(--surface); border:1px solid var(--border); border-radius:var(--rl); padding:1.25rem 1.5rem; margin-bottom:1.25rem; }\n    .grp-label { font-size:11px; font-weight:500; letter-spacing:.1em; text-transform:uppercase; color:var(--text3); margin-bottom:1rem; margin-top:1.25rem; padding-bottom:.5rem; border-bottom:1px solid var(--border); }\n    .grp-block .grp-label { margin-top:0; }\n\n    /* financial health table */\n    .fh-grid { display:flex; flex-direction:column; gap:0; border:1px solid var(--border); border-radius:var(--rl); overflow:hidden; }\n    .fh-row { display:grid; grid-template-columns:1fr 160px; align-items:start; padding:14px 14px; border-bottom:1px solid var(--surface2); background:var(--surface); gap:12px; }\n    .fh-row:last-child { border-bottom:none; }\n    .fh-row:nth-child(even) { background:#fafaf8; }\n    .fh-name { font-size:13px; font-weight:500; color:var(--text); margin-bottom:1px; }\n    .fh-fml { font-size:11px; color:var(--text3); font-style:italic; }\n    .fh-bench { font-size:10px; color:var(--amber); margin-top:1px; }\n    .fh-right { display:flex; flex-direction:column; align-items:flex-end; gap:3px; }\n    .fh-val { font-family:'DM Mono',monospace; font-size:15px; font-weight:500; }\n\n    /* Commentary box */\n    .commentary-block { margin-top:1.5rem; padding-top:1rem; border-top: 1px dashed var(--border); }\n    .commentary-box { width:100%; min-height:80px; border:1px solid var(--border); border-radius:var(--r); padding:10px 12px; font-size:13px; font-family:'DM Sans',sans-serif; color:var(--text); background:var(--surface2); resize:vertical; line-height:1.5; transition:border-color .12s; }\n    .commentary-box:focus { outline:none; border-color:var(--text); background:var(--surface); }\n    .commentary-box::placeholder { color:var(--text3); }\n    .commentary-lbl { font-size:11px; font-weight:500; letter-spacing:.06em; text-transform:uppercase; color:var(--text3); margin-bottom:6px; display:flex; align-items:center; gap:6px; }\n    .commentary-char { font-size:10px; color:var(--text3); margin-left:auto; font-weight:400; letter-spacing:0; text-transform:none; }\n    .commentary-print { display:none; font-size:11px; color:var(--text2); font-style:italic; margin-top:6px; white-space:pre-wrap; }\n\n    /* Reset buttons */\n    .btn-reset-seg { display:inline-flex; align-items:center; gap:5px; padding:5px 12px; border:1px solid var(--border); border-radius:var(--r); background:transparent; font-size:11px; font-family:'DM Sans',sans-serif; color:var(--text3); cursor:pointer; transition:all .12s; }\n    .btn-reset-seg:hover { border-color:#c0392b; color:#c0392b; background:#fff5f5; }\n    .btn-reset-data { display:inline-flex; align-items:center; gap:4px; padding:4px 9px; border:1px solid var(--border); border-radius:var(--r); background:transparent; font-size:11px; font-family:'DM Sans',sans-serif; color:var(--text3); cursor:pointer; transition:all .12s; margin-left:6px; }\n    .btn-reset-data:hover { border-color:#c0392b; color:#c0392b; background:#fff5f5; }\n    .seg-hdr-actions { display:flex; align-items:center; gap:8px; flex-wrap:wrap; justify-content:flex-end; }\n\n    /* Period controls */\n    .period-controls { display:flex; align-items:center; gap:6px; background:var(--surface2); border-radius:20px; padding:3px; }\n    .period-controls select, .period-controls input { height:26px; border:0; background:var(--surface); border-radius:14px; padding:0 9px; font-size:12px; font-family:'DM Sans',sans-serif; color:var(--text); }\n    .period-controls input { width:74px; text-align: center; font-family: 'DM Mono', monospace; }\n    .period-btn { width:26px; height:26px; border:0; border-radius:50%; background:transparent; color:var(--text2); cursor:pointer; font-size:18px; line-height:1; display:flex; align-items:center; justify-content:center; }\n    .period-btn:hover { background:var(--surface); color:var(--text); }\n\n    /* Quick status pill inside child card header */\n    .status-pill { font-size: 10px; font-weight: 500; padding: 2px 8px; border-radius: 12px; margin-left: 8px; }\n    .status-pill.completed { background: var(--green-bg); color: var(--green); }\n    .status-pill.warning { background: var(--gold-bg); color: var(--gold); }\n    .status-pill.danger { background: var(--red-bg); color: var(--red); }\n\n    /* Layout overrides & helper utilities */\n    [v-cloak] { display: none !important; }\n    .flex-center { display: flex; align-items: center; }\n    .gap-2 { gap: 8px; }\n    .gap-4 { gap: 16px; }\n    .w-full { width: 100%; }\n    .text-right { text-align: right; }\n    .text-mono { font-family: 'DM Mono', monospace; }\n    .font-bold { font-weight: 700; }\n    .mt-4 { margin-top: 1rem; }\n    .mr-2 { margin-right: 0.5rem; }\n\n    /* Modern Print Button styled with CSS variables */\n    .btn-pdf { display:inline-flex; align-items:center; gap:7px; padding:8px 18px; background:var(--text); color:#fff; border:none; border-radius:var(--r); font-size:13px; font-family:'DM Sans',sans-serif; font-weight:500; cursor:pointer; transition:opacity .15s; white-space:nowrap; flex-shrink:0; }\n    .btn-pdf:hover { opacity:.85; }\n\n    /* Print media query override */\n    @media print {\n      * { -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important; }\n      body { background:#f7f6f2 !important; margin:0; }\n      .topbar, .sidebar, #page-entry, .btn-pdf, .pdf-overlay,\n      .btn-reset-seg, .btn-reset-data, .seg-nav, .commentary-box,\n      .commentary-lbl, .commentary-char, .pill-nav { display:none !important; }\n      #page-analysis { display:block !important; min-height:auto !important; }\n      #page-analysis .main-area { padding:12px !important; max-width:100% !important; }\n      .page { display: block !important; }\n      .commentary-print { display:block !important; }\n      .grp-block { break-inside:avoid; page-break-inside:avoid; margin-bottom:10px !important; padding:12px !important; border:1px solid #e2dfd8 !important; border-radius:8px !important; }\n      .quad-grid, .quad-card { break-inside:avoid; page-break-inside:avoid; }\n      .fh-row { break-inside:avoid; page-break-inside:avoid; }\n      .a-card { break-inside:avoid; page-break-inside:avoid; margin-bottom:8px !important; }\n      .kpi-grid { grid-template-columns:repeat(4,1fr) !important; break-inside:avoid; }\n      .two-col { break-inside:avoid; }\n    }\n\n    @media(max-width:760px){\n      .sidebar{display:none;}\n      .kpi-grid,.quad-grid{grid-template-columns:1fr;}\n      .two-col{grid-template-columns:1fr;}\n      .fh-row{grid-template-columns:1fr;}\n      .topbar{height:auto;min-height:56px;gap:10px;flex-wrap:wrap;padding:.75rem 1rem;}\n      .period-controls{order:3;width:100%;justify-content:center;}\n      .pill-nav{order:2;}\n      .f-static { grid-template-columns: 1fr; gap: 4px; align-items: flex-start; }\n      .inp, .inp-t { text-align: left; }\n    }\n  </style>\n\n<style id=\"planning-suite-frame-overrides\">\n  html, body { min-height: 100%; }\n  body { margin: 0 !important; padding: 0 !important; background: #f7f6f2 !important; }\n  .topbar, .sidebar { display: none !important; }\n  .page.active { min-height: 100vh !important; display: block !important; }\n  .main-area { width: 100% !important; max-width: 1240px !important; margin: 0 auto !important; padding: 2rem !important; box-sizing: border-box !important; }\n  .container { max-width: 1240px !important; padding: 2rem !important; }\n  @media (max-width: 900px) { .main-area, .container { padding: 1rem !important; } .f-static { grid-template-columns: 1fr !important; } }\n</style>\n</head>\n<body>\n\n  <div id=\"app\" v-cloak>\n    <!-- \u2500\u2500 TOPBAR \u2500\u2500 -->\n    <div class=\"topbar\">\n      <div class=\"brand\">\n        <div class=\"brand-mark\">\n          <svg viewBox=\"0 0 24 24\"><path d=\"M22 10v6M2 10l10-5 10 5-10 5z\"/><path d=\"M6 12v5c0 2 2 3 6 3s6-1 6-3v-5\"/></svg>\n        </div>\n        <div>\n          <span class=\"brand-name\">NurtureFund</span>\n          <span class=\"brand-sub\">Education Planner</span>\n        </div>\n      </div>\n\n      <!-- Pill view switcher -->\n      <div class=\"pill-nav\">\n        <button class=\"pill-btn\" :class=\"{active: activeTab === 'setup'}\" @click=\"activeTab = 'setup'\">\n          <i data-lucide=\"edit-3\" style=\"width: 14px; height: 14px;\"></i>\n          Setup\n        </button>\n        <button class=\"pill-btn\" :class=\"{active: activeTab === 'analysis'}\" @click=\"activeTab = 'analysis'\">\n          <i data-lucide=\"bar-chart-3\" style=\"width: 14px; height: 14px;\"></i>\n          Dashboard\n        </button>\n      </div>\n\n      <!-- System Current Year configuration -->\n      <div class=\"period-controls\">\n        <span style=\"font-size: 11px; font-weight: 500; color: var(--text3); margin-left: 6px;\">Current Year:</span>\n        <button class=\"period-btn\" @click=\"decrementYear\" title=\"Previous Year\">\u2212</button>\n        <input type=\"number\" v-model.number=\"currentSystemYear\" min=\"2020\" max=\"2100\">\n        <button class=\"period-btn\" @click=\"incrementYear\" title=\"Next Year\">+</button>\n      </div>\n    </div>\n\n    <!-- \u2500\u2500 APPLICATION SHELL \u2500\u2500 -->\n    <div class=\"page active\">\n      \n      <!-- \u2500\u2500 SIDEBAR \u2500\u2500 -->\n      <div class=\"sidebar\">\n        <div class=\"sidebar-top\">\n          <div class=\"sb-label\">Navigation</div>\n          \n          <a class=\"sb-item\" :class=\"{active: activeTab === 'setup'}\" @click=\"activeTab = 'setup'\">\n            <div class=\"sb-dot d2\"></div>\n            <span>Plan & Setup</span>\n          </a>\n          <a class=\"sb-item\" :class=\"{active: activeTab === 'analysis'}\" @click=\"activeTab = 'analysis'\">\n            <div class=\"sb-dot d1\"></div>\n            <span>Summary & Metrics</span>\n          </a>\n\n          <!-- Profile completeness tracker -->\n          <div class=\"prog-wrap\">\n            <div class=\"prog-top\">\n              <span>Profile Progress</span>\n              <span>{{ completenessPercentage }}%</span>\n            </div>\n            <div class=\"prog-track\">\n              <div class=\"prog-fill\" :style=\"{width: completenessPercentage + '%'}\"></div>\n            </div>\n          </div>\n\n          <div class=\"sb-label\">Active Segments</div>\n          <!-- Dynamic per-segment children summaries in sidebar -->\n          <div v-for=\"(child, index) in children\" :key=\"child.id\" class=\"seg-sum on\">\n            <div class=\"ss-head\" :class=\"'q' + ((index % 4) + 1)\" :style=\"{background: getCardThemeColor(index)}\">\n              {{ child.name || 'Child #' + (index + 1) }}\n            </div>\n            <div class=\"ss-body\">\n              <div class=\"ss-row\">\n                <span>Age / Year:</span>\n                <span class=\"ss-v ss-b\">{{ child.currentAge }}y / {{ child.collegeYear }}</span>\n              </div>\n              <div class=\"ss-row\">\n                <span>Years to Go:</span>\n                <span class=\"ss-v\">{{ getYearsToGo(child) }} yrs</span>\n              </div>\n              <div class=\"ss-row\">\n                <span>Est. Target Fund:</span>\n                <span class=\"ss-v ss-b\">{{ formatCurrency(calculateFutureCost(child)) }}</span>\n              </div>\n              <div class=\"ss-row\">\n                <span>Monthly Save:</span>\n                <span class=\"ss-v positive\">{{ formatCurrency(calculateMonthlySavings(child)) }}</span>\n              </div>\n            </div>\n          </div>\n\n          <div v-if=\"children.length === 0\" style=\"padding: 0 1.25rem; font-size: 12px; color: var(--text3); font-style: italic;\">\n            No children added yet.\n          </div>\n        </div>\n\n        <!-- Sidebar footer controls -->\n        <div style=\"padding: 1rem; border-top: 1px solid var(--border);\">\n          <button class=\"btn-reset-data w-full\" @click=\"resetToDefaults\" style=\"justify-content: center;\">\n            <i data-lucide=\"rotate-ccw\" style=\"width: 12px; height: 12px;\"></i>\n            Reset Planner Data\n          </button>\n        </div>\n      </div>\n\n      <!-- \u2500\u2500 MAIN CONTENT AREA \u2500\u2500 -->\n      \n      <!-- PAGE 1: PLAN & SETUP -->\n      <div v-if=\"activeTab === 'setup'\" id=\"page-entry\" class=\"main-area\">\n        <div class=\"seg-hdr\">\n          <div>\n            <div class=\"seg-tag t1\">Strategic Financial Planning</div>\n            <h1 class=\"seg-title\">Children Education Planner</h1>\n            <p class=\"seg-desc\">Estimate college tuition and living allowances inflation-adjusted to age 18, and calculate the savings required to fulfill the tuition gap.</p>\n          </div>\n          \n          <div class=\"seg-hdr-actions\">\n            <div class=\"seg-tot-box\">\n              <div class=\"tot-label\">Estimated Future Costs</div>\n              <div class=\"tot-val\">{{ formatCurrency(totalFutureCostSum) }}</div>\n            </div>\n          </div>\n        </div>\n\n        <!-- Children List -->\n        <div class=\"grp-block\">\n          <div class=\"grp-label\">Children Education Profiles</div>\n          \n          <div v-for=\"(child, index) in children\" :key=\"child.id\" class=\"card\">\n            <!-- Card Header (Expandable) -->\n            <div class=\"ch\" :class=\"{open: child.expanded}\" @click=\"toggleChildExpand(child)\">\n              <div class=\"ch-left\">\n                <div class=\"ci\" :class=\"getCardThemeClass(index)\">\n                  <i data-lucide=\"user\" style=\"width: 14px; height: 14px;\"></i>\n                </div>\n                <div>\n                  <span class=\"ch-title\">{{ child.name || 'Child #' + (index + 1) }}</span>\n                  <div class=\"ch-sub\">\n                    Entering college in {{ child.collegeYear }} ({{ getYearsToGo(child) }} years from now)\n                  </div>\n                </div>\n              </div>\n              <div class=\"ch-right\" @click.stop>\n                <div class=\"ch-sum\">\n                  {{ formatCurrency(calculateFutureCost(child)) }}\n                </div>\n                <button class=\"btn-rm\" @click.stop=\"removeChild(child.id)\" title=\"Remove child profile\">\n                  <i data-lucide=\"trash-2\" style=\"width: 14px; height: 14px;\"></i>\n                </button>\n                <div class=\"chev\" :class=\"{open: child.expanded}\" @click.stop=\"toggleChildExpand(child)\">\n                  <i data-lucide=\"chevron-down\" style=\"width: 16px; height: 16px;\"></i>\n                </div>\n              </div>\n            </div>\n\n            <!-- Card Body / Settings Form -->\n            <div class=\"cb\" :class=\"{open: child.expanded}\">\n              <!-- Child Identity Details -->\n              <div class=\"f-static\">\n                <div>\n                  <div class=\"f-label\">Child's Name</div>\n                  <div class=\"f-sub\">Used for reports and tracking</div>\n                </div>\n                <input type=\"text\" class=\"inp-t\" v-model=\"child.name\" placeholder=\"Enter name\">\n              </div>\n\n              <!-- Age / Timing Variables -->\n              <div class=\"f-static\">\n                <div>\n                  <div class=\"f-label\">Current Age</div>\n                  <div class=\"f-sub\">Used to calculate target college enrollment year</div>\n                </div>\n                <div class=\"pfx-wrap\">\n                  <input type=\"number\" class=\"inp pr\" v-model.number=\"child.currentAge\" min=\"0\" max=\"18\" @input=\"updateYearFromAge(child)\">\n                  <span class=\"sfx\">yrs</span>\n                </div>\n              </div>\n\n              <div class=\"f-static\">\n                <div>\n                  <div class=\"f-label\">Expected Year to Enter College</div>\n                  <div class=\"f-sub\">Usually reached at age 18</div>\n                </div>\n                <div class=\"pfx-wrap\">\n                  <input type=\"number\" class=\"inp pr\" v-model.number=\"child.collegeYear\" :min=\"currentSystemYear\" max=\"2150\">\n                  <span class=\"sfx\">Year</span>\n                </div>\n              </div>\n\n              <div class=\"f-static\">\n                <div>\n                  <div class=\"f-label\">Years of College Duration</div>\n                  <div class=\"f-sub\">Standard undergrad is typically 3 to 4 years</div>\n                </div>\n                <div class=\"pfx-wrap\">\n                  <input type=\"number\" class=\"inp pr\" v-model.number=\"child.collegeDuration\" min=\"1\" max=\"10\">\n                  <span class=\"sfx\">Years</span>\n                </div>\n              </div>\n\n              <!-- Cost Variables -->\n              <div class=\"f-static\">\n                <div>\n                  <div class=\"f-label\">Current Annual College Tuition Fee</div>\n                  <div class=\"f-sub\">Present value of standard yearly tuition</div>\n                </div>\n                <div class=\"pfx-wrap\">\n                  <span class=\"pfx\">$</span>\n                  <input type=\"number\" class=\"inp pl\" v-model.number=\"child.currentAnnualFee\" min=\"0\">\n                </div>\n              </div>\n\n              <div class=\"f-static\">\n                <div>\n                  <div class=\"f-label\">Current Annual Living Allowance</div>\n                  <div class=\"f-sub\">Present value of room, board, and utilities</div>\n                </div>\n                <div class=\"pfx-wrap\">\n                  <span class=\"pfx\">$</span>\n                  <input type=\"number\" class=\"inp pl\" v-model.number=\"child.currentLivingAllowance\" min=\"0\">\n                </div>\n              </div>\n\n              <!-- Economic Drivers -->\n              <div class=\"f-static\">\n                <div>\n                  <div class=\"f-label\">Expected College Education Inflation</div>\n                  <div class=\"f-sub\">Historical education inflation is typically 4% - 6%</div>\n                </div>\n                <div class=\"pfx-wrap\">\n                  <input type=\"number\" class=\"inp pr\" v-model.number=\"child.educationInflation\" step=\"0.1\" min=\"0\" max=\"30\">\n                  <span class=\"sfx\">%</span>\n                </div>\n              </div>\n\n              <div class=\"f-static\">\n                <div>\n                  <div class=\"f-label\">Current Funds Already Saved</div>\n                  <div class=\"f-sub\">Existing portfolio allocated for this child</div>\n                </div>\n                <div class=\"pfx-wrap\">\n                  <span class=\"pfx\">$</span>\n                  <input type=\"number\" class=\"inp pl\" v-model.number=\"child.currentSavings\" min=\"0\">\n                </div>\n              </div>\n\n              <div class=\"f-static\">\n                <div>\n                  <div class=\"f-label\">Target Investment Rate of Return</div>\n                  <div class=\"f-sub\">Expected compound annual growth rate of savings</div>\n                </div>\n                <div class=\"pfx-wrap\">\n                  <input type=\"number\" class=\"inp pr\" v-model.number=\"child.investmentReturn\" step=\"0.1\" min=\"0\" max=\"30\">\n                  <span class=\"sfx\">%</span>\n                </div>\n              </div>\n\n              <!-- Calculated Projections inside the Card -->\n              <div class=\"fh-grid mt-4\">\n                <div class=\"fh-row\">\n                  <div>\n                    <div class=\"fh-name\">Years Remaining to Prepare</div>\n                    <div class=\"fh-fml\">Formula: expectedCollegeYear - Current Year</div>\n                  </div>\n                  <div class=\"fh-right\">\n                    <span class=\"fh-val\">{{ getYearsToGo(child) }} Years</span>\n                  </div>\n                </div>\n\n                <div class=\"fh-row\">\n                  <div>\n                    <div class=\"fh-name\">Total Tuition Cost in Enrollment Year</div>\n                    <div class=\"fh-fml\">Future Value of tuition fee: FV = PV \u00d7 (1 + inflation)^n</div>\n                    <div class=\"fh-bench\">PV = Current Fee \u00d7 Duration = {{ formatCurrency(child.currentAnnualFee * child.collegeDuration) }}</div>\n                  </div>\n                  <div class=\"fh-right\">\n                    <span class=\"fh-val font-bold\">{{ formatCurrency(calculateFutureTuitionOnly(child)) }}</span>\n                  </div>\n                </div>\n\n                <div class=\"fh-row\">\n                  <div>\n                    <div class=\"fh-name\">Total Living Allowance in Enrollment Year</div>\n                    <div class=\"fh-fml\">Future Value of living allowance: FV = PV \u00d7 (1 + inflation)^n</div>\n                    <div class=\"fh-bench\">PV = Current Allowance \u00d7 Duration = {{ formatCurrency(child.currentLivingAllowance * child.collegeDuration) }}</div>\n                  </div>\n                  <div class=\"fh-right\">\n                    <span class=\"fh-val font-bold\">{{ formatCurrency(calculateFutureAllowanceOnly(child)) }}</span>\n                  </div>\n                </div>\n\n                <div class=\"fh-row\">\n                  <div>\n                    <div class=\"fh-name\">Combined Total Education Cost (Target)</div>\n                    <div class=\"fh-fml\">Grand target college education fund</div>\n                  </div>\n                  <div class=\"fh-right\">\n                    <span class=\"fh-val positive font-bold text-mono\">{{ formatCurrency(calculateFutureCost(child)) }}</span>\n                  </div>\n                </div>\n\n                <div class=\"fh-row\">\n                  <div>\n                    <div class=\"fh-name\">Monthly Savings Goal Needed</div>\n                    <div class=\"fh-fml\">Using compound ordinary annuity formula at {{ child.investmentReturn }}% return</div>\n                  </div>\n                  <div class=\"fh-right\">\n                    <span class=\"fh-val neutral font-bold text-mono\">{{ formatCurrency(calculateMonthlySavings(child)) }} / mo</span>\n                  </div>\n                </div>\n              </div>\n\n              <!-- EDITABLE COMMENTARY BOX (Mandatory) -->\n              <div class=\"commentary-block\">\n                <div class=\"commentary-lbl\">\n                  <span>Adviser Notes & Planning Strategy</span>\n                  <span class=\"commentary-char\">{{ child.commentary ? child.commentary.length : 0 }} / 500 chars</span>\n                </div>\n                <textarea \n                  class=\"commentary-box\" \n                  v-model=\"child.commentary\" \n                  maxlength=\"500\" \n                  placeholder=\"Draft specific saving strategies, target universities, or scholarship opportunities for this child here...\">\n                </textarea>\n              </div>\n\n            </div>\n          </div>\n\n          <!-- Add Child Button -->\n          <button class=\"btn-add\" @click=\"addNewChild\">\n            <i data-lucide=\"plus-circle\" style=\"width: 16px; height: 16px;\"></i>\n            Add Child Profile\n          </button>\n        </div>\n\n        <!-- Navigation Buttons -->\n        <div class=\"seg-nav\">\n          <div></div>\n          <button class=\"btn-nav btn-pri\" @click=\"activeTab = 'analysis'\">\n            View Financial Dashboard\n            <i data-lucide=\"arrow-right\" style=\"width: 14px; height: 14px;\"></i>\n          </button>\n        </div>\n      </div>\n\n      <!-- PAGE 2: SUMMARY & METRICS (ANALYSIS) -->\n      <div v-if=\"activeTab === 'analysis'\" id=\"page-analysis\" class=\"main-area\">\n        \n        <div class=\"a-header\">\n          <div class=\"a-header-left\">\n            <h1 class=\"a-title\">Education Portfolio Dashboard</h1>\n            <p class=\"a-sub\">Holistic portfolio metrics, funding progress trackers, and aggregate savings priorities across all children.</p>\n          </div>\n          <div>\n            <button class=\"btn-pdf\" @click=\"printDashboard\">\n              <i data-lucide=\"printer\" style=\"width: 16px; height: 16px;\"></i>\n              Print Summary PDF\n            </button>\n          </div>\n        </div>\n\n        <div v-if=\"children.length === 0\" class=\"empty-state\">\n          <i data-lucide=\"users\" style=\"width: 48px; height: 48px; stroke-width: 1.5; color: var(--text3); margin-bottom: 1rem;\"></i>\n          <h3>No children profiles loaded</h3>\n          <p class=\"mt-4\">Please <a @click=\"activeTab = 'setup'\">add at least one child profile</a> in the Setup page to begin calculation analytics.</p>\n        </div>\n\n        <div v-else>\n          <!-- KPI Summary cards -->\n          <div class=\"kpi-grid\">\n            <div class=\"kpi\">\n              <div class=\"kpi-lbl\">Total Estimated Future Target</div>\n              <div class=\"kpi-val\">{{ formatCurrency(totalFutureCostSum) }}</div>\n              <div class=\"kpi-sub\">Sum of all children's target FV</div>\n            </div>\n            <div class=\"kpi\">\n              <div class=\"kpi-lbl\">Current Savings Allocated</div>\n              <div class=\"kpi-val\">{{ formatCurrency(totalCurrentSavingsSum) }}</div>\n              <div class=\"kpi-sub\">{{ formatPercent(totalCurrentSavingsSum / (totalFutureCostSum || 1)) }} of global future target</div>\n            </div>\n            <div class=\"kpi\">\n              <div class=\"kpi-lbl\">Aggregate Net Deficit (Gap)</div>\n              <div class=\"kpi-val deficit\">{{ formatCurrency(Math.max(0, totalFutureCostSum - totalCurrentSavingsSum)) }}</div>\n              <div class=\"kpi-sub\">Total shortfall to be funded</div>\n            </div>\n            <div class=\"kpi\">\n              <div class=\"kpi-lbl\">Total Monthly Savings Needed</div>\n              <div class=\"kpi-val surplus\">{{ formatCurrency(totalMonthlySavingsSum) }}/mo</div>\n              <div class=\"kpi-sub\">Across all active children targets</div>\n            </div>\n          </div>\n\n          <!-- Quadrant Analysis -->\n          <div class=\"sec-title\">Strategic Planning Breakdown</div>\n          <div class=\"quad-grid\">\n            <!-- Quad 1: Active Targets -->\n            <div class=\"quad-card\">\n              <div class=\"q-head qg\">\n                College Fees Projections\n                <span class=\"q-hint\">Target Tuition</span>\n              </div>\n              <div class=\"q-body\">\n                <div v-for=\"child in children\" :key=\"child.id\" class=\"q-row\">\n                  <span>{{ child.name || 'Unnamed Child' }}</span>\n                  <span class=\"q-val\">{{ formatCurrency(calculateFutureTuitionOnly(child)) }}</span>\n                </div>\n                <div class=\"q-div\"></div>\n                <div class=\"q-foot\">\n                  <span>Aggregate Tuition:</span>\n                  <span class=\"q-fv\">{{ formatCurrency(totalFutureTuitionSum) }}</span>\n                </div>\n              </div>\n            </div>\n\n            <!-- Quad 2: Living Allowances -->\n            <div class=\"quad-card\">\n              <div class=\"q-head qb\">\n                Living Allowances Projections\n                <span class=\"q-hint\">Subsistence FV</span>\n              </div>\n              <div class=\"q-body\">\n                <div v-for=\"child in children\" :key=\"child.id\" class=\"q-row\">\n                  <span>{{ child.name || 'Unnamed Child' }}</span>\n                  <span class=\"q-val\">{{ formatCurrency(calculateFutureAllowanceOnly(child)) }}</span>\n                </div>\n                <div class=\"q-div\"></div>\n                <div class=\"q-foot\">\n                  <span>Aggregate Allowances:</span>\n                  <span class=\"q-fv\">{{ formatCurrency(totalFutureAllowanceSum) }}</span>\n                </div>\n              </div>\n            </div>\n\n            <!-- Quad 3: Time Horizons -->\n            <div class=\"quad-card\">\n              <div class=\"q-head qo\">\n                Preparation Time Horizons\n                <span class=\"q-hint\">Timeline Priority</span>\n              </div>\n              <div class=\"q-body\">\n                <div v-for=\"child in children\" :key=\"child.id\" class=\"q-row\">\n                  <span>{{ child.name || 'Unnamed Child' }} (Entrance {{ child.collegeYear }})</span>\n                  <span class=\"q-val warning\">{{ getYearsToGo(child) }} Years</span>\n                </div>\n                <div class=\"q-div\"></div>\n                <div class=\"q-foot\">\n                  <span>Avg Preparation Window:</span>\n                  <span class=\"q-fv\">{{ formatDecimal(averageYearsToGo) }} Years</span>\n                </div>\n              </div>\n            </div>\n\n            <!-- Quad 4: Growth Projections -->\n            <div class=\"quad-card\">\n              <div class=\"q-head qr\">\n                Growth assumptions\n                <span class=\"q-hint\">Investment Metrics</span>\n              </div>\n              <div class=\"q-body\">\n                <div v-for=\"child in children\" :key=\"child.id\" class=\"q-row\">\n                  <span>{{ child.name || 'Unnamed Child' }} Return Rate</span>\n                  <span class=\"q-val\">{{ child.investmentReturn }}%</span>\n                </div>\n                <div class=\"q-div\"></div>\n                <div class=\"q-foot\">\n                  <span>Weighted Average return:</span>\n                  <span class=\"q-fv\">{{ formatDecimal(weightedAverageReturn) }}%</span>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <!-- Funding Ratio Bars & Comparison Table -->\n          <div class=\"two-col mt-4\">\n            <!-- Ratio List card -->\n            <div class=\"a-card\">\n              <div class=\"a-card-title\">\n                <div class=\"a-dot\" style=\"background: var(--blue);\"></div>\n                Fund Progress Breakdown (Savings to Target Fund Ratio)\n              </div>\n              <div v-for=\"(child, index) in children\" :key=\"child.id\" class=\"ratio-item\">\n                <span class=\"ratio-lbl\">{{ child.name || 'Child #' + (index + 1) }}</span>\n                <div class=\"ratio-track\">\n                  <div class=\"ratio-fill\" :style=\"{ width: getFundingRatio(child) + '%', background: getCardThemeColor(index) }\"></div>\n                </div>\n                <span class=\"ratio-pct text-mono\">{{ formatPercent(getFundingRatio(child) / 100) }}</span>\n              </div>\n            </div>\n\n            <!-- Matrix Breakdown Table -->\n            <div class=\"a-card\">\n              <div class=\"a-card-title\">\n                <div class=\"a-dot\" style=\"background: var(--green);\"></div>\n                Portfolio Overview Matrix\n              </div>\n              <table class=\"bk-table\">\n                <thead>\n                  <tr>\n                    <th>Child</th>\n                    <th>Current Age</th>\n                    <th>Horizon</th>\n                    <th style=\"text-align: right;\">Monthly Target</th>\n                  </tr>\n                </thead>\n                <tbody>\n                  <tr v-for=\"child in children\" :key=\"child.id\">\n                    <td><strong>{{ child.name || 'Unnamed Child' }}</strong></td>\n                    <td>{{ child.currentAge }} Years</td>\n                    <td>{{ getYearsToGo(child) }} yrs to college</td>\n                    <td>{{ formatCurrency(calculateMonthlySavings(child)) }}</td>\n                  </tr>\n                </tbody>\n              </table>\n            </div>\n          </div>\n\n          <!-- Comprehensive Printable Adviser Notes Block -->\n          <div class=\"grp-block mt-4\">\n            <div class=\"grp-label\">Aggregated Educational Strategy Notes</div>\n            <div v-for=\"child in children\" :key=\"child.id\" style=\"margin-bottom: 1.25rem; border-bottom: 1px solid var(--border); padding-bottom: 1rem;\">\n              <div class=\"flex-center gap-2\" style=\"margin-bottom: 4px;\">\n                <span class=\"status-pill completed\" style=\"margin: 0;\">{{ child.name || 'Child' }}</span>\n                <span style=\"font-size: 11px; color: var(--text3);\">Target Year: {{ child.collegeYear }}</span>\n              </div>\n              <p style=\"font-size: 13px; color: var(--text2); line-height: 1.6; font-style: italic;\">\n                \"{{ child.commentary || 'No advisory comments provided for this profile yet. Use the setup interface to document custom scholarship, savings, or institutional directions.' }}\"\n              </p>\n              <!-- Print fallback of commentary -->\n              <div class=\"commentary-print\">\n                Adviser Strategy: {{ child.commentary || 'No specific adviser comments documented.' }}\n              </div>\n            </div>\n          </div>\n\n        </div>\n\n        <!-- Navigation Buttons -->\n        <div class=\"seg-nav\">\n          <button class=\"btn-nav\" @click=\"activeTab = 'setup'\">\n            <i data-lucide=\"arrow-left\" style=\"width: 14px; height: 14px;\"></i>\n            Back to Setup & Edit\n          </button>\n          <div></div>\n        </div>\n\n      </div>\n\n    </div>\n  </div>\n\n  <script>\n    const STORAGE_KEY = 'nurturefund_children_education_planner_v1';\n\n    const { createApp, ref, computed, watch, onMounted, nextTick } = Vue;\n\n    createApp({\n      setup() {\n        const activeTab = ref('setup');\n        const currentSystemYear = ref(2026);\n\n        // Standard default items for instant showcase\n        const defaultChildren = [\n          {\n            id: '1',\n            name: 'Sarah',\n            currentAge: 6,\n            collegeYear: 2038,\n            collegeDuration: 4,\n            currentAnnualFee: 25000,\n            currentLivingAllowance: 12000,\n            educationInflation: 4.5,\n            currentSavings: 15000,\n            investmentReturn: 6.0,\n            commentary: 'Sarah plans to study Bio-medical sciences. We need to prioritize higher return tax-sheltered educational savings plans.',\n            expanded: true\n          },\n          {\n            id: '2',\n            name: 'Marcus',\n            currentAge: 11,\n            collegeYear: 2033,\n            collegeDuration: 3,\n            currentAnnualFee: 18000,\n            currentLivingAllowance: 10000,\n            educationInflation: 4.0,\n            currentSavings: 8000,\n            investmentReturn: 5.5,\n            commentary: 'Marcus is highly interested in computing sciences. Duration estimated at 3 years in standard regional institutes.',\n            expanded: false\n          }\n        ];\n\n        const children = ref([]);\n\n        // Load data on startup\n        onMounted(() => {\n          const stored = localStorage.getItem(STORAGE_KEY);\n          if (stored) {\n            try {\n              const parsed = JSON.parse(stored);\n              children.value = parsed.children || defaultChildren;\n              currentSystemYear.value = parsed.currentSystemYear || 2026;\n            } catch (e) {\n              children.value = defaultChildren;\n            }\n          } else {\n            children.value = defaultChildren;\n          }\n          nextTick(() => {\n            lucide.createIcons();\n          });\n        });\n\n        // Sync to local storage whenever reactive state updates\n        watch([children, currentSystemYear], () => {\n          localStorage.setItem(STORAGE_KEY, JSON.stringify({\n            children: children.value,\n            currentSystemYear: currentSystemYear.value\n          }));\n          nextTick(() => {\n            lucide.createIcons();\n          });\n        }, { deep: true });\n\n        // Navigation tab watcher to render icons correctly\n        watch(activeTab, () => {\n          nextTick(() => {\n            lucide.createIcons();\n          });\n        });\n\n        // \u2500\u2500 CORE FINANCIAL FORMULAS \u2500\u2500\n\n        const getYearsToGo = (child) => {\n          const gap = child.collegeYear - currentSystemYear.value;\n          return gap > 0 ? gap : 0;\n        };\n\n        const updateYearFromAge = (child) => {\n          // Standard entrance at 18\n          const ageGap = 18 - child.currentAge;\n          child.collegeYear = currentSystemYear.value + (ageGap > 0 ? ageGap : 0);\n        };\n\n        // Calculations for individual items\n        const calculateFutureTuitionOnly = (child) => {\n          const n = getYearsToGo(child);\n          const pv = child.currentAnnualFee * child.collegeDuration;\n          const r = child.educationInflation / 100;\n          return pv * Math.pow(1 + r, n);\n        };\n\n        const calculateFutureAllowanceOnly = (child) => {\n          const n = getYearsToGo(child);\n          const pv = child.currentLivingAllowance * child.collegeDuration;\n          const r = child.educationInflation / 100;\n          return pv * Math.pow(1 + r, n);\n        };\n\n        const calculateFutureCost = (child) => {\n          return calculateFutureTuitionOnly(child) + calculateFutureAllowanceOnly(child);\n        };\n\n        // Standard compound investment calculation (PMT for ordinary annuity with compound interest)\n        const calculateMonthlySavings = (child) => {\n          const fvTarget = calculateFutureCost(child) - child.currentSavings;\n          if (fvTarget <= 0) return 0;\n\n          const n = getYearsToGo(child);\n          if (n === 0) return fvTarget; // Needs full target immediately if entering college now\n\n          const r = (child.investmentReturn / 100) / 12; // Monthly rate\n          const months = n * 12;\n\n          if (r === 0) {\n            return fvTarget / months;\n          }\n\n          // Annuity PMT Formula: PMT = (FV * r) / ((1 + r)^n - 1)\n          const pmt = (fvTarget * r) / (Math.pow(1 + r, months) - 1);\n          return pmt;\n        };\n\n        const getFundingRatio = (child) => {\n          const target = calculateFutureCost(child);\n          if (target <= 0) return 100;\n          const ratio = (child.currentSavings / target) * 100;\n          return Math.min(Math.round(ratio), 100);\n        };\n\n        // \u2500\u2500 AGGREGATE CALCULATORS \u2500\u2500\n\n        const totalFutureCostSum = computed(() => {\n          return children.value.reduce((sum, child) => sum + calculateFutureCost(child), 0);\n        });\n\n        const totalFutureTuitionSum = computed(() => {\n          return children.value.reduce((sum, child) => sum + calculateFutureTuitionOnly(child), 0);\n        });\n\n        const totalFutureAllowanceSum = computed(() => {\n          return children.value.reduce((sum, child) => sum + calculateFutureAllowanceOnly(child), 0);\n        });\n\n        const totalCurrentSavingsSum = computed(() => {\n          return children.value.reduce((sum, child) => sum + child.currentSavings, 0);\n        });\n\n        const totalMonthlySavingsSum = computed(() => {\n          return children.value.reduce((sum, child) => sum + calculateMonthlySavings(child), 0);\n        });\n\n        const averageYearsToGo = computed(() => {\n          if (children.value.length === 0) return 0;\n          const sum = children.value.reduce((sum, child) => sum + getYearsToGo(child), 0);\n          return sum / children.value.length;\n        });\n\n        const weightedAverageReturn = computed(() => {\n          if (children.value.length === 0) return 0;\n          const totalCosts = totalFutureCostSum.value;\n          if (totalCosts === 0) {\n            // Unweighted fallback\n            const sum = children.value.reduce((sum, child) => sum + child.investmentReturn, 0);\n            return sum / children.value.length;\n          }\n          const weightedSum = children.value.reduce((sum, child) => {\n            return sum + (child.investmentReturn * calculateFutureCost(child));\n          }, 0);\n          return weightedSum / totalCosts;\n        });\n\n        const completenessPercentage = computed(() => {\n          if (children.value.length === 0) return 0;\n          let points = 0;\n          let maxPoints = children.value.length * 6; // 6 primary details per child\n\n          children.value.forEach(child => {\n            if (child.name) points++;\n            if (child.currentAge > 0) points++;\n            if (child.currentAnnualFee > 0) points++;\n            if (child.currentLivingAllowance > 0) points++;\n            if (child.educationInflation > 0) points++;\n            if (child.commentary && child.commentary.trim().length > 10) points++;\n          });\n\n          return Math.round((points / maxPoints) * 100);\n        });\n\n        // \u2500\u2500 INTERACTIVE CONTROLS \u2500\u2500\n\n        const addNewChild = () => {\n          const id = Date.now().toString();\n          children.value.push({\n            id,\n            name: `Child #${children.value.length + 1}`,\n            currentAge: 5,\n            collegeYear: currentSystemYear.value + 13,\n            collegeDuration: 4,\n            currentAnnualFee: 20000,\n            currentLivingAllowance: 10000,\n            educationInflation: 4.0,\n            currentSavings: 0,\n            investmentReturn: 6.0,\n            commentary: '',\n            expanded: true\n          });\n          nextTick(() => {\n            lucide.createIcons();\n          });\n        };\n\n        const removeChild = (id) => {\n          children.value = children.value.filter(c => c.id !== id);\n        };\n\n        const toggleChildExpand = (child) => {\n          child.expanded = !child.expanded;\n        };\n\n        const incrementYear = () => {\n          currentSystemYear.value++;\n        };\n\n        const decrementYear = () => {\n          if (currentSystemYear.value > 2020) {\n            currentSystemYear.value--;\n          }\n        };\n\n        const resetToDefaults = () => {\n          if (confirm('Are you sure you want to reset all planner data to original sandbox defaults? This overwrites current input.')) {\n            children.value = JSON.parse(JSON.stringify(defaultChildren));\n            currentSystemYear.value = 2026;\n          }\n        };\n\n        const printDashboard = () => {\n          window.print();\n        };\n\n        // Styling helpers to match classes provided in CSS\n        const getCardThemeClass = (index) => {\n          const classes = ['ci1', 'ci2', 'ci3', 'ci-g'];\n          return classes[index % classes.length];\n        };\n\n        const getCardThemeColor = (index) => {\n          const colors = ['var(--green)', 'var(--blue)', 'var(--gold)', 'var(--text2)'];\n          return colors[index % colors.length];\n        };\n\n        // \u2500\u2500 UTILITIES \u2500\u2500\n\n        const formatCurrency = (val) => {\n          return new Intl.NumberFormat('en-US', {\n            style: 'currency',\n            currency: 'USD',\n            maximumFractionDigits: 0\n          }).format(val || 0);\n        };\n\n        const formatPercent = (val) => {\n          if (isNaN(val) || !isFinite(val)) return '0%';\n          return `${(val * 100).toFixed(0)}%`;\n        };\n\n        const formatDecimal = (val) => {\n          if (isNaN(val) || !isFinite(val)) return '0';\n          return val.toFixed(1);\n        };\n\n        return {\n          activeTab,\n          currentSystemYear,\n          children,\n          getYearsToGo,\n          updateYearFromAge,\n          calculateFutureTuitionOnly,\n          calculateFutureAllowanceOnly,\n          calculateFutureCost,\n          calculateMonthlySavings,\n          getFundingRatio,\n          totalFutureCostSum,\n          totalFutureTuitionSum,\n          totalFutureAllowanceSum,\n          totalCurrentSavingsSum,\n          totalMonthlySavingsSum,\n          averageYearsToGo,\n          weightedAverageReturn,\n          completenessPercentage,\n          addNewChild,\n          removeChild,\n          toggleChildExpand,\n          incrementYear,\n          decrementYear,\n          resetToDefaults,\n          printDashboard,\n          getCardThemeClass,\n          getCardThemeColor,\n          formatCurrency,\n          formatPercent,\n          formatDecimal\n        };\n      }\n    }).mount('#app');\n  </script>\n</body>\n</html>";

window.WQPlanningSuiteModules = window.WQPlanningSuiteModules || [];
window.WQPlanningSuiteModules.push({
  id: "education",
  title: "Education Planning",
  render(container) {
    container.innerHTML = '';
    const frame = document.createElement('iframe');
    frame.className = 'planning-suite-frame';
    frame.title = "Education Planning";
    frame.srcdoc = window.WQStorage?.injectScopedStorageIntoHtml?.(html, this.id) || html;
    const resizeFrame = () => {
      try {
        const doc = frame.contentDocument || frame.contentWindow?.document;
        if (!doc) return;
        const h = Math.max(760, doc.documentElement.scrollHeight, doc.body?.scrollHeight || 0);
        frame.style.height = `${h + 32}px`;
      } catch (_) {}
    };
    frame.addEventListener('load', () => {
      resizeFrame();
      let runs = 0;
      const timer = setInterval(() => {
        resizeFrame();
        runs += 1;
        if (runs > 12) clearInterval(timer);
      }, 500);
    });
    container.appendChild(frame);
  }
});

})();
